-- 무제한 범위의 SQL — 0.2 접근 필터 뒤에도 바뀌면 안 된다(설계 §4.3)
WITH r AS MATERIALIZED (SELECT NULL::bigint AS seq, NULL::int AS ord, NULL::float AS s WHERE false), o AS MATERIALIZED (SELECT u.seq FROM unit_texts u WHERE u.seq IN (SELECT b.unit_seq FROM unit_bigrams b JOIN unit_texts x ON x.seq = b.unit_seq WHERE b.space_id = ? AND b.bigram = ? AND x.text LIKE ?) AND u.space_id = ? AND NOT u.archived AND u.partition = ANY(?)), h AS (SELECT seq, ord, s FROM r UNION ALL SELECT u.seq, v.ord, v.s FROM (SELECT seq FROM r UNION SELECT seq FROM o) c JOIN unit_texts u ON u.seq = c.seq CROSS JOIN LATERAL (VALUES (0, CASE WHEN (u.text LIKE ? OR u.ctext LIKE ANY(?)) THEN CASE WHEN u.text LIKE ? THEN 1::float + (SELECT 0.5 + 0.5 * (x.m::float / (1 + x.m)) FROM (SELECT LEAST((length(u.ctext) - length(replace(u.ctext, ?, ''))) / 2, (length(u.ctext) - length(replace(u.ctext, ?, ''))) / 2, (length(u.ctext) - length(replace(u.ctext, ?, ''))) / 2) AS m) x) ELSE ((strpos(u.ctext, ?) > 0)::int + (strpos(u.ctext, ?) > 0)::int + (strpos(u.ctext, ?) > 0)::int)::float / 3 END END)) v(ord, s) WHERE v.s IS NOT NULL) SELECT u.unit_id, u.document_id, z.score FROM (SELECT h.seq, COALESCE(sum(h.s) FILTER (WHERE h.ord = 0), 0) AS score FROM h GROUP BY h.seq) z JOIN unit_texts u ON u.seq = z.seq ORDER BY z.score DESC, z.seq LIMIT ?